    private static let shadeBlob: Data = Data(base64Encoded: shadeB64)!

    static func shadeColors(_ name: String, nv: Int) -> [Float]? {
        let order = ["relax", "grip", "squeeze", "roundGrip", "roundSqueeze"]
        guard !HandPoseV2.has(name), nv == 8120, let k = order.firstIndex(of: name), shadeBlob.count >= 8120 * 6 else { return nil }
        var out = [Float](repeating: 1, count: nv * 4)
        shadeBlob.withUnsafeBytes { p in
            let b = p.bindMemory(to: UInt8.self)
            for i in 0..<nv {
                let ao = Float(b[k * 8120 + i]) / 255
                let nail = Float(b[5 * 8120 + i]) / 255
                let shade = 1 - 0.5 * ao
                // skin multiplier (diffuse is the brighter nail tone)
                let r = shade * (0.935 + 0.065 * nail)
                let g = shade * (0.90 + 0.10 * nail)
                let bl = shade * (0.83 + 0.17 * nail)
                out[i*4+0] = r; out[i*4+1] = g; out[i*4+2] = bl; out[i*4+3] = 1
            }
        }
        return out
    }
}
